     1→/**
     2→ * AnimationEngine - Frame-based animation playback controller
     3→ *
     4→ * Generic animation engine that manages an array of frame objects and provides:
     5→ * - Navigation: stepForward, stepBackward, jumpToFrame
     6→ * - Playback: play, pause, reset with requestAnimationFrame
     7→ * - Speed control: via TimingController (0.25x to 4x)
     8→ * - Events: CustomEvent 'cpu:framechange' on every frame change
     9→ * - Visibility handling: auto-pause when tab hidden
    10→ *
    11→ * Design: Decoupled from CPU state - works with any array of frame objects.
    12→ * This allows independent testing and potential reuse for other animations.
    13→ */
    14→
    15→(function() {
    16→  'use strict';
    17→
    18→  class AnimationEngine {
    19→    constructor() {
    20→      // Frame data and state
    21→      this.frames = [];
    22→      this.currentFrame = 0;
    23→      this.isPlaying = false;
    24→
    25→      // Timing controller for speed-adjusted playback
    26→      this.timing = new window.TimingController();
    27→
    28→      // RequestAnimationFrame tracking
    29→      this.rafId = null;
    30→
    31→      // Optional callback (alternative to events)
    32→      this.onFrameChange = null;
    33→
    34→      // Track visibility-based pausing
    35→      this._pausedByVisibility = false;
    36→
    37→      // Set up visibility change handler
    38→      this._setupVisibilityHandler();
    39→    }
    40→
    41→    /**
    42→     * Set up document visibility change handler
    43→     * Prevents requestAnimationFrame throttling when tab is hidden
    44→     */
    45→    _setupVisibilityHandler() {
    46→      document.addEventListener('visibilitychange', () => {
    47→        if (document.hidden) {
    48→          // Tab became hidden - pause if playing
    49→          if (this.isPlaying) {
    50→            this.pause();
    51→            this._pausedByVisibility = true;
    52→          }
    53→        } else {
    54→          // Tab became visible - resume if was auto-paused
    55→          if (this._pausedByVisibility) {
    56→            this.play();
    57→            this._pausedByVisibility = false;
    58→          }
    59→        }
    60→      });
    61→    }
    62→
    63→    // ========== FRAME LOADING ==========
    64→
    65→    /**
    66→     * Load frame array for playback
    67→     * @param {Array} framesArray - Array of frame objects (any structure)
    68→     */
    69→    loadFrames(framesArray) {
    70→      // Validate input
    71→      if (!Array.isArray(framesArray)) {
    72→        framesArray = [];
    73→      }
    74→
    75→      // Pause playback and reset position
    76→      this.pause();
    77→      this.frames = framesArray;
    78→      this.currentFrame = 0;
    79→
    80→      // Dispatch frame change event
    81→      this._dispatchFrameChange();
    82→    }
    83→
    84→    // ========== NAVIGATION METHODS ==========
    85→
    86→    /**
    87→     * Advance to next frame
    88→     * @returns {boolean} - True if moved, false if already at end
    89→     */
    90→    stepForward() {
    91→      if (this.currentFrame < this.frames.length - 1) {
    92→        this.currentFrame++;
    93→        this._dispatchFrameChange();
    94→        return true;
    95→      }
    96→      return false;
    97→    }
    98→
    99→    /**
   100→     * Go back to previous frame
   101→     * @returns {boolean} - True if moved, false if already at start
   102→     */
   103→    stepBackward() {
   104→      if (this.currentFrame > 0) {
   105→        this.currentFrame--;
   106→        this._dispatchFrameChange();
   107→        return true;
   108→      }
   109→      return false;
   110→    }
   111→
   112→    /**
   113→     * Jump to specific frame by index
   114→     * @param {number} index - Target frame index (0-based)
   115→     * @returns {boolean} - True if moved, false if index out of range
   116→     */
   117→    jumpToFrame(index) {
   118→      if (index >= 0 && index < this.frames.length) {
   119→        this.currentFrame = index;
   120→        this._dispatchFrameChange();
   121→        return true;
   122→      }
   123→      return false;
   124→    }
   125→
   126→    /**
   127→     * Get current frame object
   128→     * @returns {Object|undefined} - Current frame data
   129→     */
   130→    getCurrentState() {
   131→      return this.frames[this.currentFrame];
   132→    }
   133→
   134→    /**
   135→     * Get current frame index
   136→     * @returns {number} - Current frame index (0-based)
   137→     */
   138→    getCurrentFrameIndex() {
   139→      return this.currentFrame;
   140→    }
   141→
   142→    /**
   143→     * Get total number of frames
   144→     * @returns {number} - Total frames in loaded sequence
   145→     */
   146→    getTotalFrames() {
   147→      return this.frames.length;
   148→    }
   149→
   150→    /**
   151→     * Get playback progress information
   152→     * @returns {Object} - { current, total, percent }
   153→     */
   154→    getProgress() {
   155→      const total = this.frames.length;
   156→      const current = this.currentFrame;
   157→      // Prevent division by zero; if only 1 frame, progress is 0%
   158→      const percent = total > 1
   159→        ? (current / (total - 1)) * 100
   160→        : 0;
   161→
   162→      return {
   163→        current,
   164→        total,
   165→        percent
   166→      };
   167→    }
   168→
   169→    // ========== PLAYBACK METHODS ==========
   170→
   171→    /**
   172→     * Start automatic frame advancement
   173→     */
   174→    play() {
   175→      // Don't start if already playing or no frames loaded
   176→      if (this.isPlaying || this.frames.length === 0) {
   177→        return;
   178→      }
   179→
   180→      // If at end, reset to beginning
   181→      if (this.isAtEnd()) {
   182→        this.currentFrame = 0;
   183→        this._dispatchFrameChange();
   184→      }
   185→
   186→      this.isPlaying = true;
   187→      this.timing.reset();
   188→      this._animate(performance.now());
   189→    }
   190→
   191→    /**
   192→     * Stop automatic frame advancement
   193→     */
   194→    pause() {
   195→      this.isPlaying = false;
   196→      if (this.rafId !== null) {
   197→        cancelAnimationFrame(this.rafId);
   198→        this.rafId = null;
   199→      }
   200→    }
   201→
   202→    /**
   203→     * Toggle between play and pause
   204→     */
   205→    togglePlayPause() {
   206→      if (this.isPlaying) {
   207→        this.pause();
   208→      } else {
   209→        this.play();
   210→      }
   211→    }
   212→
   213→    /**
   214→     * Stop playback and return to first frame
   215→     */
   216→    reset() {
   217→      this.pause();
   218→      this.currentFrame = 0;
   219→      this._dispatchFrameChange();
   220→    }
   221→
   222→    /**
   223→     * Check if at first frame
   224→     * @returns {boolean}
   225→     */
   226→    isAtStart() {
   227→      return this.currentFrame === 0;
   228→    }
   229→
   230→    /**
   231→     * Check if at last frame
   232→     * @returns {boolean}
   233→     */
   234→    isAtEnd() {
   235→      return this.currentFrame >= this.frames.length - 1;
   236→    }
   237→
   238→    // ========== SPEED CONTROL ==========
   239→
   240→    /**
   241→     * Set playback speed
   242→     * @param {number} multiplier - Speed multiplier (0.25x to 4x)
   243→     * @returns {number} - Actual speed set (after clamping)
   244→     */
   245→    setSpeed(multiplier) {
   246→      return this.timing.setSpeed(multiplier);
   247→    }
   248→
   249→    /**
   250→     * Get current playback speed
   251→     * @returns {number} - Speed multiplier
   252→     */
   253→    getSpeed() {
   254→      return this.timing.speed;
   255→    }
   256→
   257→    /**
   258→     * Get human-readable speed label
   259→     * @returns {string} - Speed label like "1x", "2x"
   260→     */
   261→    getSpeedLabel() {
   262→      return this.timing.getSpeedLabel();
   263→    }
   264→
   265→    // ========== PRIVATE METHODS ==========
   266→
   267→    /**
   268→     * RequestAnimationFrame loop for automatic playback
   269→     * @param {number} currentTime - High-resolution timestamp
   270→     */
   271→    _animate(currentTime) {
   272→      // Exit if playback stopped
   273→      if (!this.isPlaying) {
   274→        return;
   275→      }
   276→
   277→      // Check if enough time has passed for next frame
   278→      if (this.timing.shouldAdvanceFrame(currentTime)) {
   279→        const moved = this.stepForward();
   280→
   281→        // If reached end, stop playback
   282→        if (!moved && this.isAtEnd()) {
   283→          this.pause();
   284→          return;
   285→        }
   286→      }
   287→
   288→      // Schedule next frame
   289→      this.rafId = requestAnimationFrame((t) => this._animate(t));
   290→    }
   291→
   292→    /**
   293→     * Dispatch frame change event and call callback
   294→     */
   295→    _dispatchFrameChange() {
   296→      const detail = {
   297→        frame: this.currentFrame,
   298→        index: this.currentFrame,  // Alias for 'frame' for test compatibility
   299→        state: this.frames[this.currentFrame],
   300→        totalFrames: this.frames.length,
   301→        isPlaying: this.isPlaying
   302→      };
   303→
   304→      // Dispatch CustomEvent
   305→      const event = new CustomEvent('cpu:framechange', { detail });
   306→      window.dispatchEvent(event);
   307→
   308→      // Call optional callback
   309→      if (typeof this.onFrameChange === 'function') {
   310→        this.onFrameChange(detail);
   311→      }
   312→    }
   313→  }
   314→
   315→  // Export to window
   316→  window.AnimationEngine = AnimationEngine;
   317→})();
   318→

