     1→/**
     2→ * TimingController - Manages playback speed and delta-time calculation
     3→ *
     4→ * Provides framerate-independent animation timing with configurable speed multipliers.
     5→ * Uses delta-time accumulation to prevent frame drift on variable refresh rate displays.
     6→ *
     7→ * Key features:
     8→ * - Speed range: 0.25x (quarter speed) to 4x (quadruple speed)
     9→ * - Base FPS: 2 (educational pace for CPU pipeline visualization)
    10→ * - Delta-time tracking prevents drift on 60Hz/120Hz/144Hz monitors
    11→ * - Named speed presets for UI convenience
    12→ */
    13→
    14→(function() {
    15→  'use strict';
    16→
    17→  class TimingController {
    18→    constructor() {
    19→      // Base frames per second for educational CPU simulation
    20→      // 2 FPS = 500ms per frame at 1x speed (time to observe each pipeline state)
    21→      this.baseFPS = 2;
    22→
    23→      // Current speed multiplier
    24→      this.speed = 1.0;
    25→
    26→      // Speed constraints
    27→      this.minSpeed = 0.25;  // Quarter speed for detailed observation
    28→      this.maxSpeed = 4.0;   // 4x speed for rapid demonstration
    29→
    30→      // Named speed presets for UI
    31→      this.speedPresets = {
    32→        slow: 0.5,
    33→        normal: 1.0,
    34→        fast: 2.0,
    35→        fastest: 4.0
    36→      };
    37→
    38→      // Timestamp tracking for delta-time calculation
    39→      this.lastFrameTime = null;
    40→    }
    41→
    42→    /**
    43→     * Set playback speed with clamping to valid range
    44→     * @param {number} multiplier - Speed multiplier (will be clamped to [minSpeed, maxSpeed])
    45→     * @returns {number} - Actual speed set (after clamping)
    46→     */
    47→    setSpeed(multiplier) {
    48→      // Clamp to valid range
    49→      this.speed = Math.max(this.minSpeed, Math.min(this.maxSpeed, multiplier));
    50→      return this.speed;
    51→    }
    52→
    53→    /**
    54→     * Calculate frame interval in milliseconds based on current speed
    55→     * @returns {number} - Milliseconds between frames
    56→     *
    57→     * Examples:
    58→     * - baseFPS=2, speed=1.0: 500ms (1000 / 2 / 1.0)
    59→     * - baseFPS=2, speed=2.0: 250ms (1000 / 2 / 2.0)
    60→     * - baseFPS=2, speed=0.5: 1000ms (1000 / 2 / 0.5)
    61→     */
    62→    getFrameInterval() {
    63→      return (1000 / this.baseFPS) / this.speed;
    64→    }
    65→
    66→    /**
    67→     * Check if enough time has passed to advance to next frame
    68→     * Uses delta-time accumulation to prevent drift
    69→     *
    70→     * @param {number} currentTime - Current timestamp from performance.now() or rAF
    71→     * @returns {boolean} - True if frame should advance
    72→     */
    73→    shouldAdvanceFrame(currentTime) {
    74→      // Initialize on first call
    75→      if (this.lastFrameTime === null) {
    76→        this.lastFrameTime = currentTime;
    77→        return false;
    78→      }
    79→
    80→      const deltaTime = currentTime - this.lastFrameTime;
    81→      const frameInterval = this.getFrameInterval();
    82→
    83→      // Check if enough time has passed
    84→      if (deltaTime >= frameInterval) {
    85→        // Update lastFrameTime with leftover accumulation to prevent drift
    86→        // If deltaTime=520ms and frameInterval=500ms, carry forward 20ms
    87→        this.lastFrameTime = currentTime - (deltaTime % frameInterval);
    88→        return true;
    89→      }
    90→
    91→      return false;
    92→    }
    93→
    94→    /**
    95→     * Reset timing state - call when starting or resuming playback
    96→     */
    97→    reset() {
    98→      this.lastFrameTime = performance.now();
    99→    }
   100→
   101→    /**
   102→     * Get current speed multiplier
   103→     * @returns {number} - Current speed value
   104→     */
   105→    getSpeed() {
   106→      return this.speed;
   107→    }
   108→
   109→    /**
   110→     * Get human-readable speed label
   111→     * @returns {string} - Speed label like "1x", "0.5x", "2x", "4x"
   112→     */
   113→    getSpeedLabel() {
   114→      // Format with 'x' suffix, show decimals only if not whole number
   115→      const speedValue = this.speed % 1 === 0 ? this.speed.toString() : this.speed.toFixed(2);
   116→      return `${speedValue}x`;
   117→    }
   118→
   119→    /**
   120→     * Apply a named speed preset
   121→     * @param {string} presetName - One of: slow, normal, fast, fastest
   122→     * @returns {boolean} - True if preset was applied, false if name invalid
   123→     */
   124→    applyPreset(presetName) {
   125→      if (this.speedPresets.hasOwnProperty(presetName)) {
   126→        this.setSpeed(this.speedPresets[presetName]);
   127→        return true;
   128→      }
   129→      return false;
   130→    }
   131→  }
   132→
   133→  // Export to window
   134→  window.TimingController = TimingController;
   135→})();
