     1→/**
     2→ * SequenceGenerator - Generates animation frame sequences from instruction lists
     3→ *
     4→ * Produces an array of CPUState snapshots representing the frame-by-frame execution
     5→ * of a RISC instruction sequence. Each instruction generates 5 frames (one per
     6→ * pipeline stage: IF, ID, EX, MEM, WB) for a NON-PIPELINED simulation.
     7→ *
     8→ * Non-pipelined execution: Each instruction completes all 5 stages before the next
     9→ * begins. This is Phase 9 behavior for educational clarity. Pipelined execution
    10→ * (multiple instructions overlapping in different stages) is Phase 12.
    11→ *
    12→ * Requires: CPUState, InstructionSet
    13→ */
    14→(function() {
    15→  'use strict';
    16→
    17→  class SequenceGenerator {
    18→    /**
    19→     * Generates a sequence of CPUState frames from an instruction array
    20→     *
    21→     * @param {Array} instructions - Array of instruction objects from InstructionSet.createInstruction()
    22→     * @param {CPUState|null} initialState - Optional initial CPU state (default: fresh state)
    23→     * @returns {object} { frames: CPUState[], instructions: instruction[], metadata: { totalCycles, totalInstructions } }
    24→     */
    25→    static generateSequence(instructions, initialState = null) {
    26→      // Create or use initial state
    27→      const state = initialState ? initialState.clone() : CPUState.createInitial();
    28→      const frames = [];
    29→
    30→      // Frame 0: Initial state
    31→      frames.push(state.clone());
    32→
    33→      // Process instructions following control flow (not just array order)
    34→      // Instructions are assumed to be at PC = index * 4 (word-aligned)
    35→      let currentState = state.clone();
    36→      let executedCount = 0;
    37→      const maxInstructions = instructions.length * 3;  // Safety limit to prevent infinite loops
    38→
    39→      while (executedCount < maxInstructions) {
    40→        // Determine which instruction to execute based on current PC
    41→        const instructionIndex = currentState.pc / 4;
    42→
    43→        // Check if PC is out of bounds (beyond instruction array)
    44→        if (instructionIndex < 0 || instructionIndex >= instructions.length || instructionIndex !== Math.floor(instructionIndex)) {
    45→          // PC is out of bounds or misaligned - stop execution
    46→          break;
    47→        }
    48→
    49→        const instruction = instructions[instructionIndex];
    50→        const instructionDef = InstructionSet.get(instruction.mnemonic);
    51→
    52→        if (!instructionDef) {
    53→          console.error(`Unknown instruction: ${instruction.mnemonic}`);
    54→          break;
    55→        }
    56→
    57→        executedCount++;
    58→
    59→        // --- IF Stage (Instruction Fetch) ---
    60→        const ifFrame = currentState.clone();
    61→        ifFrame.changedRegisters.clear();
    62→        ifFrame.changedMemory.clear();
    63→        ifFrame.activeStages.clear();
    64→
    65→        ifFrame.pipeline.IF.instruction = instruction;
    66→        ifFrame.pipeline.IF.pc = ifFrame.pc;
    67→        ifFrame.pipeline.IF.active = true;
    68→        ifFrame.activeStages.add('IF');
    69→
    70→        // Clear other stages
    71→        ifFrame.pipeline.ID.active = false;
    72→        ifFrame.pipeline.EX.active = false;
    73→        ifFrame.pipeline.MEM.active = false;
    74→        ifFrame.pipeline.WB.active = false;
    75→
    76→        ifFrame.cycleCount++;
    77→        frames.push(ifFrame);
    78→
    79→        // --- ID Stage (Instruction Decode) ---
    80→        const idFrame = frames[frames.length - 1].clone();
    81→        idFrame.changedRegisters.clear();
    82→        idFrame.changedMemory.clear();
    83→        idFrame.activeStages.clear();
    84→
    85→        idFrame.pipeline.ID.instruction = instruction;
    86→        idFrame.pipeline.ID.opcode = instruction.mnemonic;
    87→        idFrame.pipeline.ID.rs = instruction.rs || 0;
    88→        idFrame.pipeline.ID.rt = instruction.rt || 0;
    89→        idFrame.pipeline.ID.rd = instruction.rd || instruction.rt || 0;  // For I-type, rd = rt
    90→        idFrame.pipeline.ID.imm = instruction.immediate || 0;
    91→
    92→        // Read register values
    93→        idFrame.pipeline.ID.rsVal = idFrame.getRegister(instruction.rs || 0);
    94→        idFrame.pipeline.ID.rtVal = idFrame.getRegister(instruction.rt || 0);
    95→
    96→        idFrame.pipeline.ID.active = true;
    97→        idFrame.activeStages.add('ID');
    98→        idFrame.pipeline.IF.active = false;
    99→
   100→        idFrame.cycleCount++;
   101→        frames.push(idFrame);
   102→
   103→        // --- EX Stage (Execute) ---
   104→        const exFrame = frames[frames.length - 1].clone();
   105→        exFrame.changedRegisters.clear();
   106→        exFrame.changedMemory.clear();
   107→        exFrame.activeStages.clear();
   108→
   109→        // Call execute function to get ALU results
   110→        const executeResult = instructionDef.execute(exFrame, instruction);
   111→
   112→        // Store results in EX stage
   113→        exFrame.pipeline.EX.aluResult = executeResult.aluResult || 0;
   114→        exFrame.pipeline.EX.writeData = executeResult.writeData || 0;
   115→        exFrame.pipeline.EX.writeReg = executeResult.writeReg || 0;
   116→        exFrame.pipeline.EX.zero = executeResult.zero || false;
   117→        exFrame.pipeline.EX.branchTarget = executeResult.branchTarget || 0;
   118→        exFrame.pipeline.EX.jumpTarget = executeResult.jumpTarget || 0;
   119→        exFrame.pipeline.EX.memRead = executeResult.memRead || false;
   120→        exFrame.pipeline.EX.memWrite = executeResult.memWrite || false;
   121→
   122→        exFrame.pipeline.EX.active = true;
   123→        exFrame.activeStages.add('EX');
   124→        exFrame.pipeline.ID.active = false;
   125→
   126→        exFrame.cycleCount++;
   127→        frames.push(exFrame);
   128→
   129→        // --- MEM Stage (Memory Access) ---
   130→        const memFrame = frames[frames.length - 1].clone();
   131→        memFrame.changedRegisters.clear();
   132→        memFrame.changedMemory.clear();
   133→        memFrame.activeStages.clear();
   134→
   135→        // Copy EX results to MEM stage
   136→        memFrame.pipeline.MEM.writeData = memFrame.pipeline.EX.writeData;
   137→        memFrame.pipeline.MEM.writeReg = memFrame.pipeline.EX.writeReg;
   138→        memFrame.pipeline.MEM.memRead = false;
   139→        memFrame.pipeline.MEM.memWrite = false;
   140→
   141→        // Handle memory operations
   142→        if (instruction.mnemonic === 'LW') {
   143→          // Load word: read from memory
   144→          const address = memFrame.pipeline.EX.aluResult;
   145→          const memValue = memFrame.getMemory(address);
   146→          memFrame.pipeline.MEM.memData = memValue;
   147→          memFrame.pipeline.MEM.memRead = true;
   148→          memFrame.pipeline.MEM.writeData = memValue;  // Data to write back in WB
   149→        } else if (instruction.mnemonic === 'SW') {
   150→          // Store word: write to memory
   151→          const address = memFrame.pipeline.EX.aluResult;
   152→          const writeData = memFrame.pipeline.ID.rtVal;  // rt contains the data to store
   153→          memFrame.setMemory(address, writeData);
   154→          memFrame.pipeline.MEM.memWrite = true;
   155→        } else {
   156→          // Non-memory instruction: just pass through write data
   157→          memFrame.pipeline.MEM.memData = 0;
   158→        }
   159→
   160→        memFrame.pipeline.MEM.active = true;
   161→        memFrame.activeStages.add('MEM');
   162→        memFrame.pipeline.EX.active = false;
   163→
   164→        memFrame.cycleCount++;
   165→        frames.push(memFrame);
   166→
   167→        // --- WB Stage (Write Back) ---
   168→        const wbFrame = frames[frames.length - 1].clone();
   169→        wbFrame.changedRegisters.clear();
   170→        wbFrame.changedMemory.clear();
   171→        wbFrame.activeStages.clear();
   172→
   173→        wbFrame.pipeline.WB.regWrite = false;
   174→
   175→        // Write back to register if instruction writes to registers
   176→        if (InstructionSet.writesToRegister(instruction.mnemonic)) {
   177→          const writeReg = wbFrame.pipeline.MEM.writeReg;
   178→          const writeData = wbFrame.pipeline.MEM.writeData;
   179→
   180→          wbFrame.setRegister(writeReg, writeData);
   181→          wbFrame.pipeline.WB.regWrite = true;
   182→          wbFrame.pipeline.WB.writeReg = writeReg;
   183→          wbFrame.pipeline.WB.writeData = writeData;
   184→        }
   185→
   186→        // Update PC
   187→        if (instruction.mnemonic === 'BEQ') {
   188→          // Branch: if zero flag is set, take branch
   189→          if (wbFrame.pipeline.EX.zero) {
   190→            wbFrame.pc = wbFrame.pipeline.EX.branchTarget;
   191→          } else {
   192→            wbFrame.pc += 4;  // Normal PC increment
   193→          }
   194→        } else if (instruction.mnemonic === 'J') {
   195→          // Jump: unconditional jump to target
   196→          wbFrame.pc = wbFrame.pipeline.EX.jumpTarget;
   197→        } else {
   198→          // Normal instruction: PC += 4
   199→          wbFrame.pc += 4;
   200→        }
   201→
   202→        wbFrame.pipeline.WB.active = true;
   203→        wbFrame.activeStages.add('WB');
   204→        wbFrame.pipeline.MEM.active = false;
   205→
   206→        wbFrame.cycleCount++;
   207→        wbFrame.instructionCount++;
   208→
   209→        frames.push(wbFrame);
   210→
   211→        // Update currentState for next iteration (reflects PC changes from branches/jumps)
   212→        currentState = wbFrame.clone();
   213→      }
   214→
   215→      // Return complete frame sequence with metadata
   216→      return {
   217→        frames: frames,
   218→        instructions: instructions,
   219→        metadata: {
   220→          totalCycles: frames[frames.length - 1].cycleCount,
   221→          totalInstructions: frames[frames.length - 1].instructionCount
   222→        }
   223→      };
   224→    }
   225→
   226→    /**
   227→     * Generates a sequence asynchronously with progress callbacks
   228→     * Useful for longer programs (Phase 11+) to avoid blocking UI
   229→     *
   230→     * @param {Array} instructions - Array of instruction objects
   231→     * @param {CPUState|null} initialState - Optional initial CPU state
   232→     * @param {Function} onProgress - Optional progress callback (percent)
   233→     * @returns {Promise<object>} Resolves to { frames, instructions, metadata }
   234→     */
   235→    static generateSequenceAsync(instructions, initialState = null, onProgress = null) {
   236→      return new Promise((resolve) => {
   237→        const chunkSize = 10;  // Process 10 instructions at a time
   238→        let currentIndex = 0;
   239→        const allFrames = [];
   240→
   241→        // Initial state
   242→        const state = initialState ? initialState.clone() : CPUState.createInitial();
   243→        allFrames.push(state.clone());
   244→
   245→        function processChunk() {
   246→          const endIndex = Math.min(currentIndex + chunkSize, instructions.length);
   247→          const chunk = instructions.slice(currentIndex, endIndex);
   248→
   249→          // Process this chunk synchronously
   250→          const chunkResult = SequenceGenerator.generateSequence(
   251→            chunk,
   252→            allFrames[allFrames.length - 1]
   253→          );
   254→
   255→          // Append new frames (skip first frame which is duplicate of last)
   256→          allFrames.push(...chunkResult.frames.slice(1));
   257→
   258→          currentIndex = endIndex;
   259→
   260→          // Report progress
   261→          if (onProgress) {
   262→            const percent = Math.round((currentIndex / instructions.length) * 100);
   263→            onProgress(percent);
   264→          }
   265→
   266→          // Continue or finish
   267→          if (currentIndex < instructions.length) {
   268→            setTimeout(processChunk, 0);  // Yield to browser
   269→          } else {
   270→            // Done
   271→            resolve({
   272→              frames: allFrames,
   273→              instructions: instructions,
   274→              metadata: {
   275→                totalCycles: allFrames[allFrames.length - 1].cycleCount,
   276→                totalInstructions: allFrames[allFrames.length - 1].instructionCount
   277→              }
   278→            });
   279→          }
   280→        }
   281→
   282→        // Start processing
   283→        setTimeout(processChunk, 0);
   284→      });
   285→    }
   286→  }
   287→
   288→  // Export to global scope (no module bundler - vanilla JS)
   289→  if (typeof window !== 'undefined') {
   290→    window.SequenceGenerator = SequenceGenerator;
   291→  } else if (typeof global !== 'undefined') {
   292→    global.SequenceGenerator = SequenceGenerator;
   293→  }
   294→})();
   295→

