     1→/**
     2→ * CPUVisualizer - Coordinator component for CPU visualization
     3→ *
     4→ * Single entry point that:
     5→ * - Creates the complete visualization DOM structure
     6→ * - Initializes child view components (BlockDiagramView, RegisterView)
     7→ * - Listens to 'cpu:framechange' events from AnimationEngine
     8→ * - Delegates rendering to child components
     9→ *
    10→ * This is the only component that needs to be instantiated by the UI.
    11→ * Child views are managed internally.
    12→ *
    13→ * Usage:
    14→ *   const container = document.getElementById('cpu-viz-container');
    15→ *   const visualizer = new CPUVisualizer(container);
    16→ *   // Rendering happens automatically via cpu:framechange events
    17→ *   // Or manually: visualizer.render(cpuState);
    18→ */
    19→(function() {
    20→  'use strict';
    21→
    22→  class CPUVisualizer {
    23→    /**
    24→     * Creates a CPUVisualizer instance
    25→     * @param {HTMLElement} container - DOM element to render visualization into
    26→     */
    27→    constructor(container) {
    28→      this.container = container;
    29→      this.container.className = 'cpu-visualizer';
    30→
    31→      // Build the DOM structure
    32→      this._createDOM();
    33→
    34→      // Initialize child view components
    35→      this.blockDiagramView = new BlockDiagramView(
    36→        this.container.querySelector('[data-block-diagram]')
    37→      );
    38→      this.registerView = new RegisterView(
    39→        this.container.querySelector('[data-register-view]')
    40→      );
    41→
    42→      // Bind and register event listener for AnimationEngine events
    43→      this._handleFrameChange = this._handleFrameChange.bind(this);
    44→      window.addEventListener('cpu:framechange', this._handleFrameChange);
    45→    }
    46→
    47→    /**
    48→     * Creates the visualization DOM structure inside the container
    49→     * @private
    50→     */
    51→    _createDOM() {
    52→      this.container.innerHTML = `
    53→        <section class="diagram-section">
    54→          <div data-block-diagram></div>
    55→        </section>
    56→        <section class="registers-section">
    57→          <h2>Registers</h2>
    58→          <div class="register-grid" data-register-view></div>
    59→        </section>
    60→      `;
    61→    }
    62→
    63→    /**
    64→     * Handles cpu:framechange events from AnimationEngine
    65→     * @param {CustomEvent} event - Event with detail.state (CPUState)
    66→     * @private
    67→     */
    68→    _handleFrameChange(event) {
    69→      if (event.detail && event.detail.state) {
    70→        this.render(event.detail.state);
    71→      }
    72→    }
    73→
    74→    /**
    75→     * Renders the current CPU state to all child views
    76→     * Can be called manually or automatically via events
    77→     * @param {CPUState} state - Current CPU state to render
    78→     */
    79→    render(state) {
    80→      this.blockDiagramView.render(state);
    81→      this.registerView.render(state);
    82→    }
    83→
    84→    /**
    85→     * Cleans up event listeners and DOM
    86→     * Call this when removing the visualizer
    87→     */
    88→    destroy() {
    89→      window.removeEventListener('cpu:framechange', this._handleFrameChange);
    90→      this.container.innerHTML = '';
    91→      this.blockDiagramView = null;
    92→      this.registerView = null;
    93→    }
    94→  }
    95→
    96→  // Export to global scope (vanilla JS pattern)
    97→  if (typeof window !== 'undefined') {
    98→    window.CPUVisualizer = CPUVisualizer;
    99→  } else if (typeof global !== 'undefined') {
   100→    global.CPUVisualizer = CPUVisualizer;
   101→  }
   102→})();
